mapper.select:
SELECT /*NoticeMapper.selectNoticeListByInfo 공지사항 상세조회 */ ROW_NUMBER() OVER(ORDER BY ANUC_STR_YMD DESC ,AVL_PRD DESC , ANUC_TITL ASC) AS ROW_NUM ,SNO /*일련번호*/ ,ANUC_STR_YMD /*공지시작일자*/ ,ANUC_END_YMD /*공지종료일자*/ ,AVL_PRD /*유효기간*/ ,ANUC_TITL /*공지제목*/ ,ANUC_CNTNT /*공지내용*/ ,USER_NM /*사용자명*/ ,ORG_NO /*조직번호*/ ,ORG_NM /*조직명*/ ,REGNT_ENO /*등록자사번*/ ,TO_CHAR(REG_DTM, 'YYYYMMDD') AS REG_DTM /*등록일시*/ ,TRTR_ENO /*처리자사번*/ ,TO_CHAR(TRT_DTM, 'YYYYMMDD') AS TRT_DTM /*처리일시*/ FROM S_MG.TB_IMGSYF07 /* 공지사항기본 */ WHERE 1 = 1 AND USER_NM LIKE '%'||#{userNm}||'%' AND ORG_NM LIKE '%'||#{orgNm}||'%'
AND ANUC_STR_YMD BETWEEN #{anucStrYmd} AND #{anucStrYmd2}
AND ANUC_END_YMD >= TO_CHAR(systimestamp, 'YYYYMMDD')
